def convertir_octets(n):
    if n >= 1073741824:
        return "1 Go"
    elif n >= 1048576:
        mo = n // 1048576
        return f"{mo} Mo"
    elif n >= 1024:
        ko = n // 1024
        return f"{ko} Ko"
    else:
        return f"{n} octets"
```

